// The browser's glossary (generated by scripts/sync-runtime.mjs) is the reference's GLOSSARY, entry for entry.
import { describe, expect, it } from 'vitest';
import { GLOSSARY as client, LIBRARY_VERSION as clientVersion } from '~/lib/content/glossary';
import { GLOSSARY, LIBRARY_VERSION } from '~/lib/content/reference';

describe('client glossary', () => {
  it('equals the reference GLOSSARY (rerun npm run sync-runtime after editing entries.json)', () => expect(client).toEqual(GLOSSARY));
  it('has the library version', () => expect(clientVersion).toBe(LIBRARY_VERSION));
});
